// llGetNotecardLineSync example with fall back to the old dataserver read
// if llGetNotecardLineSync fails with a NAK.
string
NOTECARD_NAME
=
"notecard"
;
key
READ_KEY
=
NULL_KEY
;
key
noteCard_qry
;
integer
noteCard_line
;
default
{
state_entry
()
{
// read the notecards number of lines to the
// simulators cache memory
READ_KEY
=
llGetNumberOfNotecardLines
(
NOTECARD_NAME
);
}
dataserver
(
key
request
,
string
data
)
{
// read notecards using the new llGetNotecardLineSync function
// from simulator cache.
if
(
request
==
READ_KEY
)
{
integer
count
=
(
integer
)
data
;
integer
index
;
for
(
index
=
0
;
index
<
(
count
+
1
);
++
index
)
{
string
line
=
llGetNotecardLineSync
(
NOTECARD_NAME
,
index
);
if
(
line
==
NAK
)
{
// Got a notecard NAK meaning llGetNotecardLineSync had and error.
// falling back to the old dataserver event to read notecards.
llOwnerSay
(
"---NAK---"
);
noteCard_qry
=
llGetNotecardLine
(
NOTECARD_NAME
,
noteCard_line
);
return
;
// return is needed to break the for/next loop once the NAK is encountered.
}
else
if
(
line
==
EOF
)
{
// End of notecard.
llOwnerSay
(
"---EOF---"
);
}
else
{
// do work here.
llOwnerSay
(
line
);
}
}
}
// old system takes over if a NAK is encountered.
if
(
request
==
noteCard_qry
)
{
if
(
data
==
EOF
)
{
// End of notecard encountered.
llOwnerSay
(
"EOF encountered"
);
}
else
{
// process normal notecard line, then read the next line
// of the notecard.
llOwnerSay
(
data
);
noteCard_qry
=
llGetNotecardLine
(
NOTECARD_NAME
,
++
noteCard_line
);
}
}
}
}

